// silently render those characters as blank boxes or garbled output.
// Source: NotoSansGeorgian-{Regular,Bold}.ttf via @electron-fonts/noto-sans-georgian.
export const NOTO_SANS_GEORGIAN_REGULAR_BASE64 = "";
export const NOTO_SANS_GEORGIAN_BOLD_BASE64 = "";
